        report.warn(where, "resprouter_type", "lower case and singular, e.g. rhizome, lignotuber", resprout)
    for col in ("location_name", "resprouter_type"):
        if re.search(r"\s/\s", row[col]) or (col == "resprouter_type" and "/" in row[col]):
